def flag(name,action,when,example,result):return dict(flag=name,action=action,when=when,example=example,result=result)
def cmd(name,purpose,syntax,chapter,flags=(),situations=(),source=None):
 source=source or 'https://kubernetes.io/docs/reference/kubectl/generated/kubectl/threads/'
 if source.endswith('/threads/'):source='https://kubernetes.io/docs/reference/kubectl/'
 card = dict(name=name,aliases=[],purpose=purpose,syntax=syntax,chapter=chapter,volume='kubernetes',source=source,sources=[dict(title='Официальная документация',url=source)],flags=list(flags),situations=list(situations))
 if name == 'kubectl':
  card['persistentOptions'] = True
 return card
