cmd('etcdctl snapshot save','Получить consistent etcd snapshot с TLS credentials своего control plane.','sudo etcdctl --endpoints URL --cacert FILE --cert FILE --key FILE snapshot save FILE','21-k8s-upgrade-backup',situations=[{'problem': 'Перед обслуживанием нужен пригодный backup управляющего состояния.', 'explanation': 'Snapshot etcd содержит API-объекты, в том числе Secrets, но не содержимое прикладных PVC. Успешное сохранение не доказывает восстановление приложения.', 'solution': 'На личном cp1 используйте matching tools и TLS credentials из RECOVERY.txt, защитите файл и отдельно сохраните PKI, ключи расшифровки и данные. Проверку restore выполняют в изолированном клоне.'}],source='https://etcd.io/docs/v3.6/op-guide/recovery/'),
cmd('etcdutl snapshot restore','Восстановить новый etcd data-dir/cluster identity из snapshot при disaster recovery.','etcdutl snapshot restore FILE [RECOVERY_FLAGS]','21-k8s-upgrade-backup',[
flag('--bump-revision N --mark-compacted','Поднять revision и завершить старые watch histories по matching guide.','Kubernetes disaster recovery после fencing.','etcdutl snapshot restore backup.db --data-dir ./new-etcd --bump-revision CALCULATED_INCREMENT --mark-compacted','CALCULATED_INCREMENT — явно не готовое число/команда. Рассчитать от возможной истории; не restore поверх живого member.')],source='https://etcd.io/docs/v3.6/op-guide/recovery/'),
